<script setup lang="ts">
import{onMounted,ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import{api}from'../../api/client';import type{OrderSummary}from'../../domain/types'
const orders=ref<OrderSummary[]>([]),loading=ref(true),error=ref('');onMounted(async()=>{try{orders.value=await api.getOrders()}catch{error.value='暂时无法读取订单，请稍后重试'}finally{loading.value=false}});const open=(ref:string)=>uni.navigateTo({url:`/pages/order/detail?orderRef=${encodeURIComponent(ref)}`});const status=(code:string)=>code==='REVIEW'?'需要协助':code==='COMPLETED'?'已完成':code==='REFUND_PENDING'?'退款处理中':code==='TOPUP_RESULT_PENDING'?'充值处理中':'查看详情';const time=(value:string)=>{const d=new Date(value);return Number.isNaN(d.getTime())?'更新时间待确认':`${d.getMonth()+1}月${d.getDate()}日 ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
</script>
<template><view class="page"><AppHeader title="我的订单" left="首页" right="找回订单" @left="uni.reLaunch({url:'/pages/index/index'})" @right="uni.navigateTo({url:'/pages/order/recovery'})"/><view class="content orders"><view class="tabs"><text class="active">全部</text><text>处理中</text><text>已完成</text></view><view v-if="loading" class="card" role="status">正在加载订单…</view><view v-if="error" class="card" role="alert">{{error}}</view><button v-for="item in orders" :key="item.orderRef" class="card order" :aria-label="`查看订单 ${item.maskedPhone}`" @click="open(item.orderRef)"><view class="order-head"><text>{{time(item.updatedAt)}}</text><text :class="item.stateCode==='REVIEW'?'attention':item.stateCode==='COMPLETED'?'complete':'processing'">{{status(item.stateCode)}}</text></view><view class="order-body"><text class="operator">充</text><view><text class="phone">{{item.maskedPhone}}</text><text class="copy">手机话费充值</text></view><text class="amount">{{item.total.currency}} {{(item.total.minor/100).toFixed(2)}}</text></view><text v-if="item.stateCode==='TOPUP_RESULT_PENDING'" class="hint">正在确认充值结果，请勿重复充值</text><text v-if="item.stateCode==='REVIEW'" class="hint">结果仍在核对，你可以查看详情或联系我们</text></button><view v-if="!loading&&!error&&!orders.length" class="card empty">暂时没有订单。完成充值后，可在这里查看进度。</view></view></view></template>
<style src="../../styles/shared.css"></style><style scoped>.orders{padding-top:24rpx}.orders .heading{text-align:center;font-size:36rpx}.tabs{display:flex;margin:20rpx 0 28rpx;border-bottom:1rpx solid var(--line)}.tabs text{padding:18rpx 0;margin-right:46rpx;color:var(--muted)}.tabs .active{color:var(--brand);font-weight:800;border-bottom:4rpx solid var(--brand)}.order{width:100%;text-align:left}.order-head,.order-body{display:flex;align-items:center;justify-content:space-between}.order-head{color:var(--muted);font-size:23rpx}.order-body{margin-top:26rpx}.operator{width:72rpx;height:72rpx;line-height:72rpx;border-radius:22rpx;background:#e7effc;color:var(--brand);text-align:center;font-weight:900;flex:none;margin-right:20rpx}.order-body view{flex:1}.phone,.amount{display:block;font-weight:800}.processing{color:var(--unknown)}.complete{color:var(--success)}.attention{color:var(--risk)}.hint{display:block;margin-top:22rpx;padding-top:20rpx;border-top:1rpx solid var(--line);color:var(--muted);font-size:23rpx}.empty{text-align:center;color:var(--muted);padding:70rpx 30rpx}</style>
